#!/bin/sh
# SPDX-License-Identifier: BSD-3-Clause
# Copyright (c) 2026, kyorohiro
set -eu
ROOT_DIR=$(CDPATH= cd -- "$(dirname "$0")/.." && pwd)
cd "$ROOT_DIR"
OUT_DIR="${1:-$ROOT_DIR/dist/wasm}"
mkdir -p "$OUT_DIR"
OUT_DIR=$(CDPATH= cd -- "$OUT_DIR" && pwd)
"${EMCC:-emcc}" "$ROOT_DIR/vendor/tetorica-cdda/cdda_pcm.c" "$ROOT_DIR/wasm/cdda_wasm.c" \
  -I"$ROOT_DIR/vendor/tetorica-cdda" \
  -std=c11 -O2 -ffp-contract=off -sSTANDALONE_WASM=1 \
  -sALLOW_MEMORY_GROWTH=0 -sINITIAL_MEMORY=131072 -sSTACK_SIZE=16384 \
  --no-entry -Wl,--export-memory \
  -Wl,--export=cdda_wasm_init -Wl,--export=cdda_wasm_input \
  -Wl,--export=cdda_wasm_left -Wl,--export=cdda_wasm_right \
  -Wl,--export=cdda_wasm_prepare -Wl,--export=cdda_wasm_window \
  -Wl,--export=cdda_wasm_play -Wl,--export=cdda_wasm_pause \
  -Wl,--export=cdda_wasm_resume -Wl,--export=cdda_wasm_stop \
  -Wl,--export=cdda_wasm_seek -Wl,--export=cdda_wasm_gain \
  -Wl,--export=cdda_wasm_mute -Wl,--export=cdda_wasm_render \
  -Wl,--export=cdda_wasm_state -Wl,--export=cdda_wasm_frame \
  -Wl,--export=cdda_wasm_phase -Wl,--export=cdda_wasm_output_frames \
  -Wl,--export=cdda_wasm_get_gain -Wl,--export=cdda_wasm_muted \
  -o "$OUT_DIR/cdda_wasm.wasm"
cat > "$OUT_DIR/cdda_wasm.js" <<'EOF'
// Generated by scripts/build_cdda_wasm.sh; SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2026, kyorohiro
export const CDDA_PCM_ABI = 1;
const moduleURL = import.meta.url.replace(/[?#].*$/, '');
export const CDDA_WASM_URL = moduleURL.slice(0, moduleURL.lastIndexOf('/') + 1) + 'cdda_wasm.wasm';
EOF
